//! Machine read-model handler for Claim (issue #817).
//! Generated by codegraph-gate. DO NOT EDIT.
//!
//! The DERIVED projection the UI renders — never a machine it runs. One
//! shape for both planes: this route serves the machine read model for
//! machine-bearing entities, and (when the entity also carries a Plane B
//! workflow config) the `/workflow` payload merges the same object. The
//! UI can never offer a transition the backend would 409: buttons render
//! from `available_transitions` only, and an unknown column value is
//! VISIBLE (`state_known = false`) with an empty edge set.

use axum::extract::{Extension, Path, State};
use axum::http::HeaderMap;
use axum::Json;
use serde::Serialize;
use serde_json;
use uuid::Uuid;

use crate::app_state::AppState;
use crate::error::AppError;

/// One edge of the machine read model (issue #817): the event that fires
/// it, the state it leaves, the state it lands on, and the authored guard
/// name when the edge carries one.
#[derive(Debug, Clone, Serialize, utoipa::ToSchema)]
pub struct MachineTransitionEdge {
    pub event: String,
    pub from: String,
    pub to: String,
    pub guard: Option<String>,
}

/// The machine read model (issue #817): the kernel-derived projection
/// over the entity's status column (which the write-both transitions keep
/// in sync with the workflow instance). `machine_hash` is the FNV-1a
/// digest over the canonical machine IR — a stale render is detectable.
#[derive(Debug, Clone, Serialize, utoipa::ToSchema)]
pub struct MachineReadModelResponse {
    pub machine_id: String,
    pub current_state: String,
    pub is_terminal: bool,
    pub state_known: bool,
    pub machine_hash: String,
    pub states: Vec<String>,
    pub available_transitions: Vec<MachineTransitionEdge>,
}

/// The machine's registry id (`gate_domain_types::machines`).
const MACHINE_ID: &str = "claimstatus";

/// The machine read model for Claim `id`: load the row
/// (RLS-scoped), read the status column, derive from the kernel. This is
/// the ONE derivation — the merged `/workflow` payload reuses it when the
/// entity carries a workflow config.
pub(crate) async fn machine_read_model(
    state: &AppState,
    api_key_info: &crate::middleware::ApiKeyInfo,
    id: Uuid,
) -> Result<MachineReadModelResponse, AppError> {
    let correlation_id = Uuid::new_v4();
    let entity = state.claims_claim_queries.find_by_id(id, false, api_key_info.api_key_id, api_key_info.organization_id, api_key_info.user_id, api_key_info.role.clone()).await
        .map_err(|e| AppError::internal(format!("Failed to find Claim: {e}")).with_correlation_id(correlation_id))?
        .ok_or_else(|| AppError::not_found(format!("Claim {id} not found")).with_correlation_id(correlation_id))?;
    // The entity column is the write-both source of truth (Stage 2 keeps
    // it in sync with the workflow instance).
    let current = entity.status.as_ref().map(|v| v.to_string()).unwrap_or_default();
    let machine_json = gate_domain_types::machines::machine_json(MACHINE_ID)
        .ok_or_else(|| AppError::internal(format!("machine '{MACHINE_ID}' is not in the registry")).with_correlation_id(correlation_id))?;
    let ir: serde_json::Value = serde_json::from_str(machine_json)
        .map_err(|e| AppError::internal(format!("machine '{MACHINE_ID}' does not parse: {e}")).with_correlation_id(correlation_id))?;
    let runtime = codegraph_workflow::MachineRuntime::from_json(&ir)
        .map_err(|e| AppError::internal(format!("machine '{MACHINE_ID}' is invalid: {e}")).with_correlation_id(correlation_id))?;
    let model = runtime.read_model(&current);
    let states = runtime.state_names().into_iter().map(str::to_string).collect();
    Ok(MachineReadModelResponse {
        machine_id: model.machine_id,
        current_state: model.current_state,
        is_terminal: model.is_terminal,
        state_known: model.state_known,
        machine_hash: model.machine_hash,
        states,
        available_transitions: model
            .available_transitions
            .into_iter()
            .map(|e| MachineTransitionEdge {
                event: e.event,
                from: e.from,
                to: e.to,
                guard: e.guard,
            })
            .collect(),
    })
}

/// The machine read model for Claim (issue #817).
#[utoipa::path(
    get,

    path = "/api/v1/claims/claim/{claim_id}/machine",
    params(("claim_id" = Uuid, Path, description = "Claim ID")),

    tag = "Claim",
    responses(
        (status = 200, description = "OK", body = MachineReadModelResponse),
        (status = 404, description = "Not found"),
    )
)]
pub async fn get_machine(
    State(state): State<AppState>,
    Extension(api_key_info): Extension<crate::middleware::ApiKeyInfo>,
    headers: HeaderMap,

    Path(id): Path<Uuid>,

) -> Result<Json<serde_json::Value>, AppError> {
    let correlation_id = headers
        .get("x-correlation-id")
        .and_then(|v| v.to_str().ok())
        .and_then(|s| s.parse::<Uuid>().ok())
        .unwrap_or_else(Uuid::new_v4);
    let response = machine_read_model(&state, &api_key_info, id).await?;
    Ok(Json(serde_json::json!({
        "data": response,
        "meta": { "correlation_id": correlation_id.to_string() }
    })))
}
